-- Les coordonnées personnelles et les comptes users ne sont pas modifiés.
-- Les identifiants existants des expériences et sous-projets sont conservés.
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS cv_data_migrations (version TEXT PRIMARY KEY NOT NULL);
CREATE TEMP TABLE _cv_sync_20261010_guard (apply_update INTEGER NOT NULL);
INSERT INTO _cv_sync_20261010_guard SELECT CASE WHEN
    NOT EXISTS (SELECT 1 FROM cv_data_migrations WHERE version = '20261010-align-cv-aptineo')
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 8 AND ordre = 0)
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 9 AND ordre = 1)
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 10 AND ordre = 2)
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 11 AND ordre = 3)
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 12 AND ordre = 4)
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 13 AND ordre = 5)
    AND EXISTS (SELECT 1 FROM experiences WHERE id = 14 AND ordre = 6)
THEN 1 ELSE 0 END;
